import math

def build_agent(sandbox):
    # No structure is needed for this control-based solution
    return None

def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return
    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y
    speed = math.sqrt(vx**2 + vy**2)
    dead_zone_threshold = 0.5
    if speed < dead_zone_threshold:
        return

    # Wind compensation
    wind_force = 0.0
    if vx < 0:
        wind_force = 42.0  # Counteract left wind
    elif vx > 0:
        wind_force = -42.0  # Counteract right wind
    else:
        wind_force = 0.0

    # Pumping force
    if pos.x < 10.0:
        # Left side of pivot
        if vx > 0:
            # Moving towards pivot
            pump_force = 42.0  # Apply force to the right
        elif vx < 0:
            # Moving away from pivot
            pump_force = 42.0  # Apply force to the right to decelerate
        else:
            pump_force = 0.0
    else:
        # Right side of pivot
        if vx < 0:
            # Moving towards pivot
            pump_force = -42.0  # Apply force to the left
        elif vx > 0:
            # Moving away from pivot
            pump_force = -42.0  # Apply force to the left to decelerate
        else:
            pump_force = 0.0

    # Combine forces
    total_force_x = wind_force + pump_force
    total_force_x = max(min(total_force_x, 42.0), -42.0)

    # Vertical force to reach target
    target_y = 11.7
    if pos.y < target_y:
        # Apply vertical force upwards
        if vy > 0:
            # Moving upwards, slow down to reach apex
            vertical_force = -42.0
        elif vy < 0:
            # Moving downwards, boost upwards
            vertical_force = 42.0
        else:
            vertical_force = 42.0  # Initial boost
    else:
        vertical_force = 0.0  # No vertical force needed

    # Apply forces
    total_force_y = vertical_force
    total_force_y = max(min(total_force_y, 42.0), -42.0)
    sandbox.apply_force_to_seat(total_force_x, total_force_y)
